    public final String tag;

    private ResearchBranchType(String tag) {
        this.tag = tag;
    }

    public static ResearchBranchType valueOfTag(String tag) {
        for (ResearchBranchType type : ResearchBranchType.values()) {
            if (!type.tag.equals(tag)) continue;
            return type;
        }
        return DEFAULT;
    }
}

