public class FoodUtils {
    public static final Predicate<ItemStack> EDIBLE = itemStack -> ItemStackUtils.ISFOOD.test((ItemStack)itemStack) && !ItemStackUtils.ISCOOKABLE.test((ItemStack)itemStack);

    public static boolean canEat(ItemStack stack, IBuilding homeBuilding, IBuilding workBuilding) {
        if (!EDIBLE.test(stack) || stack.m_204117_(ModTags.poisonous_food)) {
            return false;
        }
        int homeBuildingLevel = homeBuilding == null ? 0 : homeBuilding.getBuildingLevelEquivalent();
        return FoodUtils.canEatLevel(stack, homeBuildingLevel) && (workBuilding == null || workBuilding.canEat(stack));
    }

    public static boolean canEatLevel(ItemStack stack, int buildingLevel) {
        if (stack.m_41720_() instanceof ItemCrop) {
            return false;
        }
        if (buildingLevel < 3) {
            return stack.m_41720_().getFoodProperties(stack, null) != null;
        }
        FoodProperties foodProperties = stack.m_41720_().getFoodProperties(stack, null);
        return foodProperties != null && foodProperties.m_38744_() >= buildingLevel + 1;
    }

    public static int getBuildingLevelForFood(ItemStack resource) {
        return Math.max(2, Math.min(resource.getFoodProperties(null).m_38744_() - 1, 5));
    }

    public static double getFoodValue(ItemStack foodStack, @Nullable FoodProperties itemFood, double researchBonus) {
        if (itemFood == null) {
            return 0.0;
        }
        double saturationBonus = foodStack.m_41720_() instanceof IMinecoloniesFoodItem ? 2.0 : 1.0;
        return (double)itemFood.m_38744_() * saturationBonus * (1.0 + researchBonus);
    }

    public static double getFoodValue(ItemStack foodStack, AbstractEntityCitizen citizen) {
        FoodProperties itemFood = foodStack.m_41720_().getFoodProperties(foodStack, (LivingEntity)citizen);
        double researchBonus = citizen.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(ResearchConstants.SATURATION);
        return FoodUtils.getFoodValue(foodStack, itemFood, researchBonus);
    }

